#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getGradient ( FSSpec theMeshFSSpec );OSErr getGradient ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError;	unsigned char *theMapH, *theMapL;	int i, x, y;	long meshSize, meshWidth, meshHeight;	Myth256Palette thePalette;	meshHeader theMeshHeader;	gridData *theGrid;	union gradientBytes	{		short	theShort;		char	theBytes[2];	} theGradient;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsRdPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theMapL = (unsigned char *) NewPtr (meshSize);	if ( theMapL == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theMapH = (unsigned char *) NewPtr (meshSize);	if ( theMapH == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	FileSeek ( theMeshFileRef, 1088L );	FileRead ( theGrid, theMeshHeader.meshLength, theMeshFileRef );	FSClose ( theMeshFileRef );	// make the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	// get the grid Z data into an array	for ( y = 0, i = 0; y < meshHeight * meshWidth; y += meshWidth ){		for ( x = meshWidth - 1; x >= 0; x--, i++ ){			theGradient.theShort = theGrid[i].gradient;			theMapL[x + y] = theGradient.theBytes[0];			theMapH[x + y] = theGradient.theBytes[1];		}	}	theError = writeBMP( "\p:Graphics.out:gradientL.bmp", meshWidth, meshHeight, &thePalette, (char *) theMapL );	theError = writeBMP( "\p:Graphics.out:gradientH.bmp", meshWidth, meshHeight, &thePalette, (char *) theMapH );	DisposePtr ( (Ptr) theMapL );	DisposePtr ( (Ptr) theMapH );	DisposePtr ( (Ptr) theGrid );	return theError;}